import {
    Group,
    Mesh,
    PlaneGeometry,
    RepeatWrapping,
    Color
} from 'three/webgpu';
import {
    NodeMaterial,
    texture,
    uv,
    vec2,
    vec3,
    float
} from 'three/tsl';
import { gsap } from 'gsap';
import { flyThrough } from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} [position]
 * @property {{x:number,y:number,z:number}} [rotation]
 * @property {{x:number,y:number,z:number}} [scale]
 * @property {Array<{name:string,params:any}>} [cinematicPrimitives]
 * @property {Array<string>} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {{textureLoader:(url:string)=>import('three').Texture}} textureLoader
 * @property {{fontAtlas:{createText:(txt:string,opts:any)=>import('three').Mesh}}} fontAtlas
 * @property {{[key:string]:(obj:any,params:any)=>void}} primitives
 */

/**
 * Creates the Loop Column Gallery node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
    const group = new Group();

    // apply transform from config if present
    if (config.position) group.position.set(config.position.x, config.position.y, config.position.z);
    if (config.rotation) group.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
    if (config.scale) group.scale.set(config.scale.x, config.scale.y, config.scale.z);

    // ---------- Constants ----------
    const PLATE_COUNT = 6;
    const PLATE_W = 1.9;
    const PLATE_H = 1.2;
    const PITCH = 1.5;
    const LOOP_LENGTH = PLATE_COUNT * PITCH; // 9.0
    const COL_X = 0.9;
    const BEVEL_INSET = 0.03;
    const ACCENT_W = 0.03;
    const ACCENT_COLOR = '#ff2a38';
    const INK_COLOR = '#16161d';
    const TEXT_COLOR = '#16161d';
    const ACCENT_EMISSIVE_INTENSITY = 1.4;

    // ---------- Load texture ----------
    const baseTex = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
    baseTex.wrapS = baseTex.wrapT = RepeatWrapping;

    // ---------- Helper to create NodeMaterial with fixed params ----------
    const makePlateMaterial = (tex) => {
        const mat = new NodeMaterial();
        mat.colorNode = texture(tex);
        mat.roughnessNode = float(0.6);
        mat.metalnessNode = float(0.1);
        mat.clearcoatNode = float(0.1);
        return mat;
    };

    const makeBevelMaterial = () => {
        const mat = new NodeMaterial();
        const rgb = vec3(0.0862745, 0.0862745, 0.1137255); // #16161d
        mat.colorNode = rgb;
        mat.roughnessNode = float(0.5);
        mat.metalnessNode = float(0.5);
        return mat;
    };

    const makeAccentMaterial = () => {
        const mat = new NodeMaterial();
        const rgb = vec3(1.0, 0.1647, 0.2196); // #ff2a38
        mat.colorNode = rgb;
        mat.emissiveNode = float(0.0); // start dark
        return mat;
    };

    // ---------- Geometries ----------
    const plateGeom = new PlaneGeometry(PLATE_W, PLATE_H);
    const bevelGeom = new PlaneGeometry(PLATE_W + BEVEL_INSET * 2, PLATE_H + BEVEL_INSET * 2);
    const accentGeom = new PlaneGeometry(ACCENT_W, PLATE_H);

    // ---------- Build plates ----------
    const plates = [];
    for (let i = 0; i < PLATE_COUNT; i++) {
        const baseY = i * PITCH;

        // Plate mesh
        const plateMesh = new Mesh(plateGeom.clone(), makePlateMaterial(baseTex));
        plateMesh.position.set(COL_X, baseY, 0);
        plateMesh.matrixAutoUpdate = true;

        // Bevel mesh (slightly larger, same center)
        const bevelMesh = new Mesh(bevelGeom.clone(), makeBevelMaterial());
        bevelMesh.position.copy(plateMesh.position);
        bevelMesh.matrixAutoUpdate = true;

        // Accent strip (left edge)
        const accentMesh = new Mesh(accentGeom.clone(), makeAccentMaterial());
        const accentX = COL_X - PLATE_W / 2 + ACCENT_W / 2;
        accentMesh.position.set(accentX, baseY, 0.001);
        accentMesh.matrixAutoUpdate = true;

        // Caption text (uses font atlas)
        const captionIdx = i + 1; // first entry after headline
        const captionStr = config.textContent && config.textContent[captionIdx] ? config.textContent[captionIdx] : '';
        const captionMesh = ctx.fontAtlas.createText(captionStr, {
            fontFamily: 'JetBrains Mono',
            fontWeight: 400,
            fontSize: 0.13,
            color: TEXT_COLOR,
            align: 'left'
        });
        captionMesh.position.set(-1.6, baseY, 0.01);
        captionMesh.matrixAutoUpdate = true;
        if (captionMesh.material) {
            captionMesh.material.transparent = true;
            captionMesh.material.opacity = 0.0;
        }

        // Add to group
        group.add(bevelMesh);
        group.add(plateMesh);
        group.add(accentMesh);
        group.add(captionMesh);

        plates.push({
            mesh: plateMesh,
            bevel: bevelMesh,
            accent: accentMesh,
            caption: captionMesh,
            baseY
        });
    }

    // ---------- Scroll handling ----------
    const state = {
        scrollOffset: 0,
        targetY: 0,
        scrollTimeline: null
    };

    const updatePlatePositions = () => {
        const offset = state.targetY;
        plates.forEach(p => {
            // compute wrapped y
            let y = p.baseY + offset;
            // wrap into (-LOOP_LENGTH/2, LOOP_LENGTH/2]
            while (y > LOOP_LENGTH / 2) y -= LOOP_LENGTH;
            while (y <= -LOOP_LENGTH / 2) y += LOOP_LENGTH;

            p.mesh.position.y = y;
            p.bevel.position.y = y;
            p.accent.position.y = y;
            p.caption.position.y = y;
        });
    };

    const focusClosestPlate = () => {
        let closest = null;
        let minDist = Infinity;
        plates.forEach(p => {
            const dist = Math.abs(p.mesh.position.y);
            if (dist < minDist) {
                minDist = dist;
                closest = p;
            }
        });
        plates.forEach(p => {
            if (p === closest) {
                gsap.to(p.mesh.scale, {
                    x: 1.06,
                    y: 1.06,
                    z: 1.06,
                    duration: 0.35,
                    ease: 'cubic-bezier(0.215,0.61,0.355,1)'
                });
                // accent emissive
                const accentMat = p.accent.material;
                if (accentMat instanceof NodeMaterial) {
                    // replace emissiveNode with bright value
                    accentMat.emissiveNode = float(ACCENT_EMISSIVE_INTENSITY);
                } else if (accentMat.emissive) {
                    accentMat.emissiveIntensity = ACCENT_EMISSIVE_INTENSITY;
                }
                // caption fade in
                if (p.caption.material) {
                    gsap.to(p.caption.material, { opacity: 1.0, duration: 0.5 });
                }
            } else {
                gsap.to(p.mesh.scale, {
                    x: 1,
                    y: 1,
                    z: 1,
                    duration: 0.35,
                    ease: 'cubic-bezier(0.215,0.61,0.355,1)'
                });
                const accentMat = p.accent.material;
                if (accentMat instanceof NodeMaterial) {
                    accentMat.emissiveNode = float(0.0);
                } else if (accentMat.emissive) {
                    accentMat.emissiveIntensity = 0.0;
                }
                if (p.caption.material) {
                    gsap.to(p.caption.material, { opacity: 0.0, duration: 0.5 });
                }
            }
        });
    };

    const handleScroll = (delta) => {
        state.scrollOffset += delta;
        const target = -state.scrollOffset * 1.5; // 1.5 units per scroll unit
        state.targetY = target;
        if (state.scrollTimeline) state.scrollTimeline.kill();
        state.scrollTimeline = gsap.to(state, {
            targetY: target,
            duration: 0.9,
            ease: 'cubic-bezier(0.165,0.84,0.44,1)',
            onUpdate: () => {
                updatePlatePositions();
                focusClosestPlate();
            }
        });
    };

    // expose handler
    group.userData.handlers = {
        scroll: handleScroll
    };

    // ---------- Apply cinematic primitives ----------
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach(p => {
            const fn = ctx.primitives[p.name];
            if (typeof fn === 'function') {
                fn(group, p.params);
            }
        });
    }

    // ---------- Cleanup ----------
    const cleanup = () => {
        plates.forEach(p => {
            if (p.mesh.geometry) p.mesh.geometry.dispose();
            if (p.mesh.material) p.mesh.material.dispose();
            if (p.bevel.geometry) p.bevel.geometry.dispose();
            if (p.bevel.material) p.bevel.material.dispose();
            if (p.accent.geometry) p.accent.geometry.dispose();
            if (p.accent.material) p.accent.material.dispose();
            if (p.caption && p.caption.geometry) p.caption.geometry.dispose();
            if (p.caption && p.caption.material) p.caption.material.dispose();
        });
        if (baseTex) baseTex.dispose();
        gsap.killTweensOf(state);
        plates.forEach(p => {
            gsap.killTweensOf(p.mesh.scale);
            if (p.accent.material) gsap.killTweensOf(p.accent.material);
            if (p.caption && p.caption.material) gsap.killTweensOf(p.caption.material);
        });
        group.userData.handlers = {};
    };
    group.userData.cleanup = cleanup;

    // Add headline text (first entry in textContent)
    if (config.textContent && config.textContent[0]) {
        const headlineMesh = ctx.fontAtlas.createText(config.textContent[0], {
            fontFamily: 'Lora',
            fontWeight: 600,
            fontSize: 0.62,
            color: '#16161d',
            align: 'left'
        });
        headlineMesh.position.set(-1.6, 1.9, 0);
        headlineMesh.matrixAutoUpdate = true;
        group.add(headlineMesh);
    }

    return group;
}
